import assert from "node:assert/strict";
import {readFileSync} from "node:fs";
const html=readFileSync("cal/index.html","utf8");
const js=html.match(/<script>([\s\S]*?)<\/script>/)[1];
new Function(js);
const pre=js.slice(0,js.indexOf("const $="));
const counts=new Function(pre+String.raw`let n=0;
const eq=(a,b)=>{if(a!==b)throw Error(JSON.stringify({a,b}));n++};
eq(expression('2+3*4',true),14);
eq(expression('-2^2',true),-4);
eq(expression('2^3^2',true),512);
eq(Math.abs(expression('sin(30)',true)-.5)<1e-9,true);
eq(acquisition(600000000,1,false,false)[0],6000000);
eq(acquisition(700000000,1,false,false)[3],.0167);
eq(acquisition(500000000,2,true,true)[0],40000000);
eq(Math.abs(gainTax(2e9,1e9,0,15,0,false,0).tax-257010000)<1,true);
eq(Math.abs(gainTax(2e9,1e9,0,15,0,false,.2).tax-582510000)<1,true);
eq(Math.abs(gainTax(2e9,1e9,0,15,0,false,.3).tax-682260000)<1,true);
eq(gainTax(12e8,6e8,0,5,3,true,0).tax,0);
eq(propertyTax(7e8,false,false,3e8).base,321000000);
eq(comprehensiveTax(12e8,1,true,65,10,0).total,0);
eq(propertyCreditEstimate(1e8,1000000,1000000),60000);
eq(salaryInsurance(3100000)[3],27900);
eq(salaryInsurance(8e6,'H1')[0],302570);
eq(salaryInsurance(8e6,'H2')[0],313020);
eq(Math.abs(interest(1e6,.05,2,1)-102500)<.001,true);
let boundary=0;
for(const r of TAX_DATA_2026.rows)for(let f=1;f<=11;f++){
 let expected=r[f+1]<1000?0:r[f+1];
 eq(tableWithholding(r[0]*1000,f,0,1),expected);
 eq(tableWithholding(r[1]*1000-1,f,0,1),expected);
 boundary+=2;
}
eq(tableWithholding(3100000,1,0,.8),66320);
eq(tableWithholding(1e7,4,2,1),1125010);
return {assertions:n,boundary};
`)();
const scope={};
new Function("globalThis",readFileSync("cal/vendor/korean-lunar-calendar.js","utf8"))(scope);
const cal=new scope.KoreanLunarCalendar();
let dates=0;
for(let t=Date.UTC(1900,0,1);t<=Date.UTC(2050,11,31);t+=86400000){
 const d=new Date(t),y=d.getUTCFullYear(),m=d.getUTCMonth()+1,a=d.getUTCDate();
 assert.equal(cal.setSolarDate(y,m,a),true);
 const l=cal.getLunarCalendar();
 assert.equal(cal.setLunarDate(l.year,l.month,l.day,!!l.intercalation),true);
 const v=cal.getSolarCalendar();
 assert.deepEqual([v.year,v.month,v.day],[y,m,a]);dates++;
}
assert.equal(cal.setLunarDate(2024,1,1,true),false);
assert.equal(cal.setSolarDate(2025,2,29),false);
assert.equal(cal.setSolarDate(2026,2,17),true);
assert.deepEqual(cal.getLunarCalendar(),{year:2026,month:1,day:1,intercalation:false});
const fx=js.slice(js.indexOf("const currencies="),js.indexOf("function showFxRates"));
const parse=new Function(fx+'\nfunction nowKST(){return "2026-11-26"};return parseFx;')();
const observed={base:"EUR",date:"2026-11-25",rates:{CNY:7.2999,JPY:174.22,KRW:1471.19,USD:1.0935}};
assert.equal(parse(observed).rates.EUR,1471.19);
assert.equal(parse(observed).rates.USD,1471.19/1.0935);
assert.throws(()=>parse({...observed,date:"2026-11-01"}));
assert.throws(()=>parse({...observed,base:"KRW"}));
assert.throws(()=>parse({...observed,rates:{KRW:1471.19}}));
console.log(JSON.stringify({status:"PASS",...counts,lunarRoundTrips:dates,fxObservedFixture:true}));
